	/**
	 * Finds out whether a tree holds anything that preparation acts on: a VALUES block whose rows are not captured yet,
	 * or a SELECT subquery, whose inherited graph context may be lowered. It visits the same nodes as the preparation
	 * passes but skips the children of nodes that can hold neither.
	 */
	private static final class PreparationDemand extends AbstractQueryModelVisitor<RuntimeException> {
		private boolean needed;
		/** Receives every node this walk passes; a node already in it is known to need nothing and is not entered. */
		private Set<QueryModelNode> passed;

		boolean isNeededFor(QueryModelNode expression, Set<QueryModelNode> passed) {
			needed = false;
			this.passed = passed;
			try {
				expression.visit(this);
			} finally {
				this.passed = null;
			}
			return needed;
		}

		@Override
		public void meet(BindingSetAssignment assignment) {
			// Rows that are captured already, or that their source declares stable, are left as they are by the
			// capture pass. Only the first preparation of a query finds anything else; the twenty-odd that follow,
			// one per optimizer, then need no pass at all.
			Iterable<BindingSet> source = assignment.getBindingSets();
			if (source != null && !(source instanceof PreparedRows) && !isStableRowSource(source)) {
				needed = true;
			} else if (passed != null) {
				passed.add(assignment);
			}
		}

		@Override
		public void meet(Projection projection) {
			if (projection.isSubquery()) {
				needed = true;
			} else {
				super.meet(projection);
			}
		}

		@Override
		public void meet(StatementPattern pattern) {
			// Only variables below.
			if (passed != null) {
				passed.add(pattern);
			}
		}

		@Override
		public void meet(ProjectionElemList elements) {
			// Only names below.
		}

		@Override
		public void meet(Var var) {
			// A leaf.
		}

		@Override
		protected void meetNode(QueryModelNode node) {
			if (needed || passed != null && !passed.add(node)) {
				return;
			}
			super.meetNode(node);
		}
	}

	/** One preparation phase owns node aliases and captures a producer only once, including optimizer additions. */
	private static final class CaptureSession implements QueryModelPreparation {
		private final Map<QueryModelNode, QueryModelNode> preparedNodes = new IdentityHashMap<>();
		private final Map<Iterable<BindingSet>, PreparedRows> capturedRows = new IdentityHashMap<>();
		private boolean closed;

		@Override
		public QueryModelNode prepare(QueryModelNode expression) {
			if (closed) {
				return expression;
			}
			QueryModelNode known = preparedNodes.get(expression);
			if (known != null) {
				return known;
			}
			expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
				@Override
				protected void meetNode(QueryModelNode node) {
					if (!preparedNodes.containsKey(node)) {
						super.meetNode(node);
						preparedNodes.put(node, node);
					}
				}

				@Override
				public void meet(BindingSetAssignment assignment) {
					QueryModelNode alias = preparedNodes.get(assignment);
					if (alias == assignment) {
						return;
					}
					Iterable<BindingSet> source = assignment.getBindingSets();
					if (source == null || source instanceof PreparedRows || isStableRowSource(source)) {
						// An already stable source needs no defensive copy.
						preparedNodes.put(assignment, assignment);
						return;
					}
					PreparedRows rows = capturedRows.computeIfAbsent(source, PreparedRows::new);
					BindingSetAssignment prepared = assignment.clone();
					prepared.setBindingSets(rows);
					preparedNodes.put(assignment, prepared);
					preparedNodes.put(prepared, prepared);
					if (assignment != expression) {
						assignment.replaceWith(prepared);
					}
				}
			});
			// Extension nodes may deliberately keep their visitor traversal opaque. Preparation still preserves
			// their root and any children that the extension exposed to this visitor.
			preparedNodes.putIfAbsent(expression, expression);
			return preparedNodes.get(expression);
		}

		@Override
		public void invalidate(QueryModelNode changedNode) {
			for (QueryModelNode current = changedNode; current != null; current = current.getParentNode()) {
				preparedNodes.remove(current);
			}
		}

		@Override
		public void resetTraversal() {
			if (!preparedNodes.isEmpty()) {
				preparedNodes.clear();
			}
		}

		@Override
		public void close() {
			closed = true;
			if (!preparedNodes.isEmpty()) {
				preparedNodes.clear();
			}
			if (!capturedRows.isEmpty()) {
				capturedRows.clear();
			}
		}
	}

	/** The marker prevents recursive precompile and cloned prepared trees from recapturing rows. */
	/** Immutable rows (or a source that declares itself repeatable) are stable without a preparation copy. */
	private static boolean isStableRowSource(Iterable<BindingSet> source) {
		if (source instanceof BindingSetAssignment.RepeatableBindingSetSource) {
			return true;
		}
		if (!(source instanceof List<?> rows)) {
			return false;
		}
		for (Object row : rows) {
			if (row != EmptyBindingSet.getInstance() && (row == null || row.getClass() != ListBindingSet.class)) {
				return false;
			}
		}
		return true;
	}

	private static final class PreparedRows extends AbstractList<BindingSet>
			implements Serializable, BindingSetAssignment.RepeatableBindingSetSource {
		private static final long serialVersionUID = 1L;
		private final List<BindingSet> rows;

		private PreparedRows(Iterable<BindingSet> source) {
			List<BindingSet> captured = new ArrayList<>();
			for (BindingSet row : source) {
				List<String> names = new ArrayList<>(row.getBindingNames());
				List<Value> values = new ArrayList<>(names.size());
				for (String name : names) {
					values.add(row.getValue(name));
				}
				captured.add(new SnapshotRow(names, values));
			}
			rows = Collections.unmodifiableList(captured);
		}

		@Override
		public BindingSet get(int index) {
			return rows.get(index);
		}

		@Override
		public int size() {
			return rows.size();
		}
	}

	private static final class SnapshotRow extends ListBindingSet {
		private static final long serialVersionUID = 1L;
		private final Set<String> names;

		private SnapshotRow(List<String> names, List<Value> values) {
			super(Collections.unmodifiableList(names), Collections.unmodifiableList(values));
			this.names = Collections.unmodifiableSet(new LinkedHashSet<>(names));
		}

		@Override
		public Set<String> getBindingNames() {
			return names;
		}
	}
